        c.g[A0][0] = Addr(gp(c, -0xc8)).lw(c);
        call_ptr(c, callee::LOBBY_MAN_REQUEST_STATS_PAGE, 0x001c_4b8c)?;
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
