        let connected = c.g[V0][0] != 0;
        c.g[V0][0] = c.lw(gpa(c, 0x238));
        if !connected {
            c.cycles += 3;
            c.g[A0][0] = c.lw(gpa(c, 0x238));
            call_ptr(c, 0x0026_13c8, 0x001a_be9c)?; // BuddyMan_Reconnect
            c.g[V0][0] = c.lw(gpa(c, 0x238));
        }
        c.cycles += 2;
