        c.g[A0][0] = sx((c.g[A0][0] as u32).wrapping_sub(0x20c0));
        call_ptr(c, 0x0031_7670, 0x001a_9b0c)?; // StrHash
        c.g[A0][0] = c.g[S0][0];
        c.g[A2][0] = 0;
        c.g[A1][0] = c.g[V0][0];
        call_ptr(c, 0x0039_a568, 0x001a_9b1c)?; // UIListBox_AddItemStrId
