            Addr(frame.at(c, 0x890)).sd(c, c.g[T0][0]);
            Addr(frame.at(c, 0x898)).sd(c, c.g[T1][0]);
            Addr(frame.at(c, 0x8a0)).sd(c, c.g[T2][0]);
            Addr(frame.at(c, 0x8a8)).sd(c, c.g[T3][0]);
            c.swc1(12, frame.at(c, 0x870));
            c.swc1(14, frame.at(c, 0x874));
