                                    call_ptr(c, 0x00317d70, 0x001a95d4)?;
                                    c.g[A1][0] = c.lw((c.g[S0][0] as u32).wrapping_add(0x10));
                                    c.g[RA][0] = sx(0x001a95e0);
                                    c.g[A0][0] = c.g[V0][0];
                                    call_ptr(c, 0x001b1f88, 0x001a95e0)?;
