            if call_ptr(c, t, 0x001a3edc).is_err() {
                return;
            }
            c.g[RA][0] = sx(0x001a3ee4);
            c.g[A0][0] = c.g[S0][0];
            c.pc = 0x001a5450;
            ee::s03::cFEStateNetMessenger_ClearNameList(c);
            if c.pc != 0x001a3ee4 {
                return;
            }
            c.g[A0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(0x6e8));
            c.g[V0][0] = c.lw((c.g[S0][0] as u32).wrapping_add(0x6f0));
            c.g[V1][0] = c.g[A0][0];
