pub(crate) const POPUP_SELF_POWER_UPS: u32 = 0x6e4;

pub(crate) const POPUP_SELF_MULTIPLIERS: u32 = 0x6e8;

pub(crate) const POPUP_SELF_POINTICONS: u32 = 0x6ec;

