        frame.save(c, S2, 0x130);
        frame.save(c, S3, 0x120);
        frame.save_ra(c, 0x100);
        c.g[V0][0] = Addr(r32(c, S4).wrapping_add(0x40)).lw(c);
        let no_screen = c.g[V0][0] == 0;
