                call_ptr(c, 0x0031_7670, 0x001b_1888)?;
                c.g[A0][0] = Addr(r32(c, S4).wrapping_add(0x40)).lw(c);
                c.g[A1][0] = c.g[V0][0];
                call_ptr(c, 0x0039_d860, 0x001b_1894)?;
                c.g[S3][0] = c.g[V0][0];
                let none = c.g[S3][0] == 0;
                c.g[V0][0] = Addr(r32(c, GP).wrapping_sub(0xc8)).lw(c);
                if none {
                    break 'r;
                }
                c.cycles += 9;
                c.g[A0][0] = c.g[S3][0];
