                c.g[A2][0] = c.g[V0][0];
                c.g[A0][0] = c.g[SP][0];
                c.g[A1][0] = sx((c.g[A1][0] as u32).wrapping_add(0x1a88));
                call_ptr(c, 0x002c_2718, 0x001b_1930)?;
