        c.g[A0][0] = sx(0x0046_0000u32.wrapping_add(0x5b38));
        call_ptr(c, 0x0031_7670, 0x001c_21e8)?;
        let title = c.g[V0][0];
        Addr(r32(c, S0)).off(0x54).sw(c, title);
        c.g[A0][0] = sx(0x0046_0000u32.wrapping_add(0x5b50));
