    /// A vtable for `*(obj + 8)` whose two slots call the fake (delta 0, so
    /// the callee is `obj` itself).
    pub(crate) fn plain_vtable(c: &mut Cpu, r: &mut Rng) -> u32 {
        vtable(c, r, &[0x40, 0x48])
    }

