    /// An action/key code covering the small ranges the handlers switch on.
    pub(crate) fn action_key(seed: u32, r: &mut Rng) -> u64 {
        match seed % 8 {
            0 => 0,
            1 => 3,
            2 => 5,
            3 => 6,
            4 => 7,
            5 => 8,
            6 => 9,
            _ => (r.next_u32() as u64) << 8 | (r.next_u32() % 4) as u64,
        }
    }

