    // A setup wrapper that also runs `alloc_base_3`.
    pub(crate) fn alloc_base_setup<'a>(
        f: impl Fn(&mut Cpu, u32, &mut Rng) + 'a,
    ) -> impl Fn(&mut Cpu, u32) + 'a {
        move |c, seed| {
            let mut r = alloc_base_3(c, seed, 0x1250, 3);
            f(c, seed, &mut r);
        }
    }

