                c.bus.write32(DATA + 0x8000 + 0x6d0, DATA + 0x9000);
                c.bus.write32(DATA + 0x8000 + 0x40, DATA + 0xa000);
                c.bus.write32(DATA + 0xa000 + 0xd0, DATA + 0xb000);
                c.bus.write32(DATA + 0x8000 + 0x10, DATA + 0xc000);
